package br.com.tapeteskalke.service;
import br.com.tapeteskalke.dto.OperacaoDtos.CompraRequest; import br.com.tapeteskalke.dto.OperacaoDtos.CompraResponse; import br.com.tapeteskalke.dto.OperacaoDtos.CancelarRequest; import br.com.tapeteskalke.entity.*; import br.com.tapeteskalke.exception.*; import br.com.tapeteskalke.repository.*; import br.com.tapeteskalke.security.CurrentUser; import java.math.*; import java.time.*; import java.util.*; import org.springframework.http.HttpStatus; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class CompraService { private final CompraRepository compras; private final FornecedorRepository fornecedores; private final ProdutoService produtos; private final EstoqueService estoque; private final PermissionService permissions; private final CurrentUser current; private final Clock clock; public CompraService(CompraRepository compras,FornecedorRepository fornecedores,ProdutoService produtos,EstoqueService estoque,PermissionService permissions,CurrentUser current,Clock clock){this.clock=clock;this.compras=compras;this.fornecedores=fornecedores;this.produtos=produtos;this.estoque=estoque;this.permissions=permissions;this.current=current;}
 @Transactional public CompraResponse create(CompraRequest r){permissions.action("compras_criar");if((r.fornecedorId()==null||r.fornecedorId().isBlank())&&(r.fornecedorNomeManual()==null||r.fornecedorNomeManual().isBlank()))throw new BusinessException("FORNECEDOR_OBRIGATORIO","Informe fornecedor cadastrado ou manual",HttpStatus.UNPROCESSABLE_ENTITY);var c=new Compra();c.setFornecedor(r.fornecedorId()==null||r.fornecedorId().isBlank()?null:fornecedores.findById(r.fornecedorId()).orElseThrow(()->new ResourceNotFoundException("Fornecedor",r.fornecedorId())));c.setFornecedorNomeManual(r.fornecedorNomeManual());c.setDataCompra(r.dataCompra());c.setObservacoes(r.observacoes());c.setCreatedBy(current.require().id());c.setUpdatedBy(current.require().id());BigDecimal total=BigDecimal.ZERO;Map<String,Produto> locked=new LinkedHashMap<>();for(var i:r.itens().stream().sorted(Comparator.comparing(br.com.tapeteskalke.dto.OperacaoDtos.CompraItem::produtoId)).toList())locked.put(i.produtoId(),produtos.locked(i.produtoId()));for(var input:r.itens()){var p=locked.get(input.produtoId());if(!p.isAtivo())throw new BusinessException("PRODUTO_INATIVO","Produto inativo: "+p.getNome(),HttpStatus.CONFLICT);var item=new CompraItem();item.setProduto(p);item.setDestinoEstoque(input.destinoEstoque());item.setQuantidade(input.quantidade());item.setPrecoUnitario(input.precoUnitario());item.setSubtotal(input.quantidade().multiply(input.precoUnitario()).setScale(2,RoundingMode.HALF_UP));item.setProdutoNomeSnapshot(p.getNome());c.addItem(item);total=total.add(item.getSubtotal());}c.setTotalCusto(total);compras.save(c);for(var item:c.getItens())estoque.change(item.getProduto(),item.getDestinoEstoque(),item.getQuantidade(),"ENTRADA_COMPRA","COMPRA",c.getId(),"Compra");return response(c);}
 @Transactional public CompraResponse cancel(String id,CancelarRequest r){permissions.action("compras_cancelar");var c=compras.detail(id).orElseThrow(()->new ResourceNotFoundException("Compra",id));if(!"FINALIZADA".equals(c.getStatus()))throw new BusinessException("COMPRA_NAO_CANCELAVEL","Compra não pode ser cancelada",HttpStatus.CONFLICT);for(var item:c.getItens().stream().sorted(Comparator.comparing(i->i.getProduto().getId())).toList()){var p=produtos.locked(item.getProduto().getId());estoque.change(p,item.getDestinoEstoque(),item.getQuantidade().negate(),"ESTORNO_COMPRA","CANCELAMENTO",c.getId(),"Cancelamento da compra");}c.setStatus("CANCELADA");c.setCancelledAt(OffsetDateTime.now(clock));c.setCancelledBy(current.require().id());c.setMotivoCancelamento(r.motivo());c.setUpdatedBy(current.require().id());return response(c);} @Transactional(readOnly=true) public List<CompraResponse> list(){return compras.listWithSupplier().stream().map(this::response).toList();} private CompraResponse response(Compra c){return new CompraResponse(c.getId(),c.getDataCompra(),c.getFornecedor()!=null?c.getFornecedor().getNomeEmpresa():c.getFornecedorNomeManual(),c.getTotalCusto(),c.getStatus());}
}